import { computed } from 'vue'

const props = withDefaults(
  defineProps<{
    label?: string
    value?: string
    delta?: string
    caption?: string
    accent?: 'lime' | 'sky' | 'amber'
  }>(),
  {
    label: '月度经常性收入',
    value: '¥ 248k',
    delta: '+18.4%',
    caption: '较上月',
    accent: 'lime',
  },
)

const accentColor = computed(() => {
  if (props.accent === 'sky') return 'var(--theme-secondary)'
  if (props.accent === 'amber') return '#fbbf24'
  return 'var(--theme-primary)'
})
